// ESLint (flat config). npm run lint / npm run lint:fix
import js from '@eslint/js';
import globals from 'globals';
import prettier from 'eslint-config-prettier';

export default [
  { ignores: ['dist/', '.cache/', 'node_modules/', 'videos/'] },

  js.configs.recommended,

  // The game: classic scripts (no modules) that share the global object G.
  {
    files: ['src/js/**/*.js'],
    languageOptions: {
      ecmaVersion: 2022,
      sourceType: 'script',
      globals: {
        ...globals.browser,
        G: 'writable'
      }
    }
  },

  // Data generated by scripts/*.py: not linted.
  { ignores: ['src/js/data/pokedex.js', 'src/js/data/sprites-meta.js'] },

  // Service worker.
  {
    files: ['public/sw.js'],
    languageOptions: { sourceType: 'script', globals: { ...globals.serviceworker } }
  },

  // Save merging: also loaded by the server with require.
  {
    files: ['src/js/core/save-merge.js'],
    languageOptions: { globals: { module: 'readonly' } }
  },

  // The server (server/): Node modules.
  {
    files: ['server/**/*.mjs'],
    languageOptions: { ecmaVersion: 2022, sourceType: 'module', globals: { ...globals.node } }
  },

  // Node scripts (build...).
  {
    files: ['scripts/**/*.js'],
    languageOptions: { sourceType: 'commonjs', globals: { ...globals.node } }
  },

  {
    rules: {
      'no-unused-vars': ['warn', { args: 'none', caughtErrors: 'none' }],
      // Variables get a default value even if overwritten later (e.g. before a try).
      'no-useless-assignment': 'off',
      'no-empty': ['error', { allowEmptyCatch: true }]
    }
  },

  // Last: turns off the style rules that Prettier already handles.
  prettier
];
